import{_ as i,a0 as r,w as l,s as u,I as s,x as t,a1 as o,A as a,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"如何在 Linux 桌面添加用户 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 桌面添加用户 | LCTT (201911) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 桌面添加用户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 桌面添加用户 | LCTT (201911) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201911/20191107 How to add a user to your Linux desktop","title":"如何在 Linux 桌面添加用户","tag":"201911","desc":""},"relativePath":"201911/20191107 How to add a user to your Linux desktop.md","filePath":"[post].md"}'),p={name:"201911/20191107 How to add a user to your Linux desktop.md"};function m(f,e,g,x,L,T){const n=r("Link");return l(),u("div",null,[e[20]||(e[20]=s("h1",{id:"如何在-linux-桌面添加用户",tabindex:"-1"},[t("如何在 Linux 桌面添加用户 "),s("a",{class:"header-anchor",href:"#如何在-linux-桌面添加用户","aria-label":"Permalink to “如何在 Linux 桌面添加用户”"},"​")],-1)),e[21]||(e[21]=s("blockquote",null,[s("p",null,"無論是在安裝過程中還是在桌面中，通過圖形界面管理用户都非常容易。")],-1)),e[22]||(e[22]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/team_global_people_gis_location.png?itok=Rl2IKo12",alt:"Team of people around the world",title:"Team of people around the world"})],-1)),e[23]||(e[23]=s("p",null,"添加用户是你在一個新系統上要做的第一件事。而且，你通常需要在計算機的整個生命週期中管理用户。",-1)),s("p",null,[e[1]||(e[1]=t("我的關於 ",-1)),o(n,{href:"https://opensource.com/article/19/10/linux-useradd-command"},{default:a(()=>[...e[0]||(e[0]=[t("useradd 命令",-1)])]),_:1}),e[2]||(e[2]=t("文章提供了更深入的對 Linux 的用户管理的瞭解。",-1)),e[3]||(e[3]=s("code",null,"useradd",-1)),e[4]||(e[4]=t(" 是一個命令列工具，但是你也可以在 Linux 上以圖形方式管理用户。這就是本文的主題。",-1))]),e[24]||(e[24]=d('<h3 id="在-linux-安裝過程中添加用户" tabindex="-1">在 Linux 安裝過程中添加用户 <a class="header-anchor" href="#在-linux-安裝過程中添加用户" aria-label="Permalink to “在 Linux 安裝過程中添加用户”">​</a></h3><p>大多數 Linux 發行版都提供了在安裝過程中創建用户的步驟。例如，Fedora 30 安裝程序 Anaconda 創建標準的 <code>root</code> 用户和另一個本地用户帳户。在安裝過程中進入“配置”頁面時，單擊“用户設置”下的“用户創建”。</p><p><img src="https://opensource.com/sites/default/files/uploads/screenshot_fedora30_anaconda2.png" alt="Fedora Anaconda Installer - Add a user" title="Fedora Anaconda Installer - Add a user"></p><p>在用户創建頁面上，輸入用户的詳細信息：全名、用户名和密碼。你還可以選擇是否使用户成為管理員。</p><p><img src="https://opensource.com/sites/default/files/uploads/screenshot_fedora30_anaconda3.png" alt="Create a user during installation" title="Create a user during installation"></p><p>點擊“高級”按鈕打開“高級用户配置”頁面。如果需要除默認設置以外的其他設置，那麼可以在此處指定主目錄的路徑以及用户和組 ID。你也可以輸入用户所屬的其他組。</p><p><img src="https://opensource.com/sites/default/files/uploads/screenshot_fedora30_anaconda4.png" alt="Advanced user configuration" title="Advanced user configuration"></p><h3 id="在-linux-桌面上添加用户" tabindex="-1">在 Linux 桌面上添加用户 <a class="header-anchor" href="#在-linux-桌面上添加用户" aria-label="Permalink to “在 Linux 桌面上添加用户”">​</a></h3><h4 id="gnome" tabindex="-1">GNOME <a class="header-anchor" href="#gnome" aria-label="Permalink to “GNOME”">​</a></h4><p>許多 Linux 發行版都使用 GNOME 桌面。以下截圖來自 Red Hat Enterprise Linux 8.0，但是在其他發行版（如 Fedora、Ubuntu 或 Debian）中，該過程相似。</p><p>首先打開“設置”。然後打開“詳細”，選擇“用户”，單擊“解鎖”，然後輸入密碼（除非你已經以 root 用户登錄）。這樣將用“添加用户”按鈕代替“解鎖”按鈕。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome_settings_user_unlock.png" alt="GNOME user settings" title="GNOME user settings"></p><p>現在，你可以通過單擊“添加用户”，然後選擇“帳户類型”然後輸入“用户名”和“密碼”來添加用户。</p><p>在下面的截圖中，已經輸入了用户名，設置保留為默認設置。我不必輸入“用户名”，因為它是在我在“全名”字段中輸入時自動創建的。如果你不喜歡自動補全，你仍然可以對其進行修改。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome_settings_adding_user.png" alt="GNOME settings - add user" title="GNOME settings - add user"></p><p>這將為名為 Sonny 的用户創建一個標準帳户。Sonny 首次登錄時需要提供密碼。</p><p>接下來，將顯示用户。在此頁面可以選擇每個用户進行自定義或者刪除。例如，你可能想選擇一個頭像或設置默認語言。</p><p><img src="https://opensource.com/sites/default/files/uploads/gnome_settings_user_new.png" alt="GNOME new user" title="GNOME new user"></p><h4 id="kde" tabindex="-1">KDE <a class="header-anchor" href="#kde" aria-label="Permalink to “KDE”">​</a></h4><p>KDE 是另一個流行的 Linux 桌面環境。下面是 Fedora 30 上 KDE Plasma 的截圖。你可以看到，在 KDE 中添加用户與在 GNOME 中添加用户非常相似。</p><p><img src="https://opensource.com/sites/default/files/uploads/kde_settings_adding_user.png" alt="KDE settings - add user" title="KDE settings - add user"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>除 GNOME 和 KDE 外，其他桌面環境和窗口管理器也有圖形用户管理工具。無論是在安裝時還是安裝後，在 Linux 中以圖形方式添加用户都是快速簡便的。</p><hr>',24)),s("p",null,[e[6]||(e[6]=t("via: ",-1)),o(n,{href:"https://opensource.com/article/19/11/add-user-gui-linux"},{default:a(()=>[...e[5]||(e[5]=[t("https://opensource.com/article/19/11/add-user-gui-linux",-1)])]),_:1})]),s("p",null,[e[11]||(e[11]=t("作者：",-1)),o(n,{href:"https://opensource.com/users/alanfdoss"},{default:a(()=>[...e[7]||(e[7]=[t("Alan Formy-Duval",-1)])]),_:1}),e[12]||(e[12]=t(" 選題：",-1)),o(n,{href:"https://github.com/lujun9972"},{default:a(()=>[...e[8]||(e[8]=[t("lujun9972",-1)])]),_:1}),e[13]||(e[13]=t(" 譯者：",-1)),o(n,{href:"https://github.com/geekpi"},{default:a(()=>[...e[9]||(e[9]=[t("geekpi",-1)])]),_:1}),e[14]||(e[14]=t(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[10]||(e[10]=[t("wxy",-1)])]),_:1})]),s("p",null,[e[17]||(e[17]=t("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[15]||(e[15]=[t("LCTT",-1)])]),_:1}),e[18]||(e[18]=t(" 原創編譯，",-1)),o(n,{href:"https://linux.cn/"},{default:a(()=>[...e[16]||(e[16]=[t("Linux中國",-1)])]),_:1}),e[19]||(e[19]=t(" 榮譽推出",-1))])])}const h=i(p,[["render",m]]);export{b as __pageData,h as default};
